public static int min(Node<Integer> first) {
    int min = first.getValue();
    Node<Integer> p = first.getNext();
    while (p != null) {
        if (p.getValue() < min) {
            min = p.getValue();
        }
        p = p.getNext();
    }
    return min;
}

public static int count(Node<Integer> first, int x) {
    int count = 0;
    Node<Integer> p = first;
    while (p != null) {
        if (p.getValue() == x) {
            count++;
        }
        p = p.getNext();
    }
    return count;
}

